import { describe, expect, it } from 'vitest';
import { differenceScript, structureScript } from '../../../src/features/structure/script';
import { diffStructure } from '../../../src/features/structure/steps';
import { collection, database, differenceOf, index, int, view, workedExample } from './build';

const options = { database: 'shop', left: 'dev › shop', right: 'prod › shop' };

const withoutDrops = `// Makes prod › shop like dev › shop.
// Generated by Datardo (Compare structure).
// Steps that drop something are commented out: remove the // in front of them to run them too.

use("shop");

// orders: index status_1 – Missing on the right: { status: 1 }
db.getCollection("orders").createIndex({ status: 1 });

// users: options – Different validator
db.runCommand({ collMod: "users", validator: {} });

// recent: view – View missing on the right (on orders)
db.createView("recent", "orders", [{ $sort: { date: -1 } }]);

// big: view – View missing on the right (on recent)
db.createView("big", "recent", [{ $match: { total: { $gt: 100 } } }]);

// legacy: collection – Collection only on the right
// Its documents and indexes are deleted.
// DESTRUCTIVE, optional: remove the // to run it.
// db.getCollection("legacy").drop();

// orders: index old_1 – Only on the right: { old: 1 }
// DESTRUCTIVE, optional: remove the // to run it.
// db.getCollection("orders").dropIndex("old_1");
`;

describe('structure.script', () => {
  it('gives exactly the script of the worked example', () => {
    expect(structureScript(workedExample(), { ...options, drops: false })).toBe(withoutDrops);
  });

  it('runs the drops with Include drops in the script', () => {
    const script = structureScript(workedExample(), { ...options, drops: true });
    expect(script).toContain(
      '// Steps marked DESTRUCTIVE drop indexes, collections or data: check them before running the script.',
    );
    expect(script).not.toContain('commented out');
    expect(
      script.endsWith(`// legacy: collection – Collection only on the right
// Its documents and indexes are deleted.
// DESTRUCTIVE
db.getCollection("legacy").drop();

// orders: index old_1 – Only on the right: { old: 1 }
// DESTRUCTIVE
db.getCollection("orders").dropIndex("old_1");
`),
    ).toBe(true);
  });

  it('says nothing is to change when the structures are the same', () => {
    const same = database([collection('orders', { indexes: [index('a_1', { a: int(1) })] })]);
    const { differences } = diffStructure(same, same);
    expect(structureScript(differences, { ...options, drops: false })).toBe(`// Makes prod › shop like dev › shop.
// Generated by Datardo (Compare structure).

use("shop");

// Nothing to change: the structures are the same.
`);
  });

  it('creates a view before the view on it, whatever their names', () => {
    const left = database([collection('orders'), view('a_on_z', 'z_on_orders'), view('z_on_orders', 'orders')]);
    const script = structureScript(diffStructure(left, database([collection('orders')])).differences, {
      ...options,
      drops: false,
    });
    expect(script.indexOf('db.createView("z_on_orders"')).toBeLessThan(script.indexOf('db.createView("a_on_z"'));
  });

  it('puts // in front of every line of a destructive command of several lines', () => {
    const left = database([collection('orders', { options: { capped: true, size: int(4096) } })]);
    const long = { name: { $exists: true }, email: { $exists: true }, created: { $exists: true } };
    const right = database([collection('orders'), collection('legacy_customers_of_the_old_shop', {})]);
    const differences = diffStructure(left, right).differences;
    const recreated = diffStructure(
      database([
        collection('orders', {
          indexes: [index('main', { a: int(1) }, { unique: true, partialFilterExpression: long })],
        }),
      ]),
      database([collection('orders', { indexes: [index('main', { a: int(1) })] })]),
    ).differences;
    const main = differenceOf(recreated, 'orders', 'index', 'main');
    const lines = differenceScript(main, 'shop', false).trimEnd().split('\n');
    const create = lines.slice(lines.lastIndexOf('// DESTRUCTIVE, optional: remove the // to run it.') + 1);
    expect(create.length).toBeGreaterThan(1);
    expect(create.every((line) => line.startsWith('// '))).toBe(true);
    expect(structureScript(differences, { ...options, drops: false })).toContain(
      '// db.runCommand({ convertToCapped: "orders", size: 4096 });',
    );
  });

  it('writes the commands of rule 7', () => {
    const left = database(
      [
        collection('c', {
          options: { capped: true, size: int(4096) },
          indexes: [index('mine', { a: int(1) }, { unique: true })],
          searchIndexes: [
            { name: 'default', type: 'search', definition: { mappings: { dynamic: true } } },
            { name: 'vectors', type: 'vectorSearch', definition: { fields: [] } },
          ],
        }),
        {
          ...view('v', 'c', [{ $match: { a: int(1) } }]),
          options: {
            viewOn: 'c',
            pipeline: [{ $match: { a: int(1) } }],
            collation: { locale: 'fr' },
          },
        },
      ],
      { search: 'ok' },
    );
    const script = structureScript(diffStructure(left, database([], { search: 'ok' })).differences, {
      ...options,
      drops: false,
    });
    expect(script).toContain('db.createCollection("c", { capped: true, size: 4096 });');
    expect(script).toContain('db.getCollection("c").createIndex({ a: 1 }, { unique: true, name: "mine" });');
    expect(script).toContain('db.getCollection("c").createSearchIndex("default", { mappings: { dynamic: true } });');
    expect(script).toContain('db.getCollection("c").createSearchIndex("vectors", "vectorSearch", { fields: [] });');
    expect(script).toContain('db.createView("v", "c", [{ $match: { a: 1 } }], { collation: { locale: "fr" } });');
  });
});
